def _nearest(summaries, t):
    """The compaction summary record is written a few ms before its boundary."""
    best = None
    for k in summaries:
        if abs((ts(k) - ts(t)).total_seconds()) < 5 and (best is None or abs((ts(k) - ts(t)).total_seconds()) < abs((ts(best) - ts(t)).total_seconds())):
            best = k
    return best


def _agent_stats(p):
    n = 0; t0 = None; t1 = None; toks = 0; seen = set()
    for line in open(p):
        try:
            r = json.loads(line)
        except Exception:
            continue
        n += 1
        if r.get('timestamp'):
            t0 = t0 or r['timestamp']; t1 = r['timestamp']
        if r.get('type') == 'assistant':
            m = r.get('message', {})
            if m.get('id') not in seen:
                seen.add(m.get('id')); toks += (m.get('usage') or {}).get('output_tokens', 0) or 0
    return n, t0, t1, toks


