            if nxt:
                fh.write('- context at the first API call after (%s): **%s tokens** (input %s, cache read %s, cache creation %s)\n' % (nxt['ts'], nxt['context_in'], nxt['input'], nxt['cache_read'], nxt['cache_creation']))
            hs = [h for h in humans if h[0] > b['ts']]
